import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M2 11c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2m11-7c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2m3 4.5A2.5 2.5 0 0 0 13.5 6c-.98 0-1.82.57-2.23 1.39-.6-.78-1.51-1.3-2.56-1.36.18-.49.29-.99.29-1.53C9 2.01 6.99 0 4.5 0S0 2.01 0 4.5 2.01 9 4.5 9c.19 0 .37-.03.56-.06-.03.19-.06.37-.06.56C5 11.43 6.57 13 8.5 13c1.63 0 2.98-1.11 3.37-2.62.44.38 1 .62 1.63.62A2.5 2.5 0 0 0 16 8.5M14.5 13c-.83 0-1.5.67-1.5 1.5s.67 1.5 1.5 1.5 1.5-.67 1.5-1.5-.67-1.5-1.5-1.5"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M18 16a2 2 0 1 1 0 4 2 2 0 0 1 0-4M2.5 14a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5M6 0a6 6 0 0 1 5.606 8.137 4.5 4.5 0 0 1 1.728.868A3.5 3.5 0 1 1 16.5 14c-.59 0-1.147-.148-1.635-.406a4.5 4.5 0 0 1-8.837-1.595L6 12A6 6 0 1 1 6 0m10.5 0a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5"] as readonly string[];

export const HeatmapIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="heatmap" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
HeatmapIcon.displayName = `Blueprint6.Icon.HeatmapIcon`;

/**
 * @deprecated Use {@link HeatmapIcon} instead.
 */
export const Heatmap: typeof HeatmapIcon = HeatmapIcon;

export default HeatmapIcon;
